// Auto-generated Okine font base64 for jsPDF
export const OKINE_BOLD_BASE64 = "";

export const OKINE_REGULAR_BASE64 = "";

export function registerOkineFont(doc: any): boolean {
  try {
    doc.addFileToVFS('Okine-Bold.ttf', OKINE_BOLD_BASE64);
    doc.addFont('Okine-Bold.ttf', 'Okine', 'bold');
    doc.addFileToVFS('Okine-Regular.ttf', OKINE_REGULAR_BASE64);
    doc.addFont('Okine-Regular.ttf', 'Okine', 'normal');
    doc.addFont('Okine-Regular.ttf', 'Okine', 'italic');
    return true;
  } catch (err) {
    console.warn('Could not register Okine font with jsPDF:', err);
    return false;
  }
}
